using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Accounts.Admin;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Users;[Authorize(Policy="AccountAdmin")]public sealed class EditModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public Guid MemberKey{get;private set;}public string Name{get;private set;}="";public string Profile{get;private set;}="";public IEnumerable<string>Profiles=>ProfilePermissionMatrix.AccountProfiles.Where(x=>ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",x));public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();var row=await(from m in db.AccountMembers.AsNoTracking()join u in db.Users.AsNoTracking()on m.UserId equals u.Id where m.Id==id&&m.AccountId==account&&!m.IsDeleted select new{m.Id,m.RoleCode,u.Name}).SingleOrDefaultAsync(ct);if(row is null)return NotFound();MemberKey=row.Id;Profile=row.RoleCode;Name=row.Name;return Page();}public async Task<IActionResult>OnPostAsync(Guid id,string profile,CancellationToken ct){if(!ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",profile))return Forbid();return await Change(id,ct,m=>m.RoleCode=profile,"AccountUserProfileChanged",$"Perfil alterado para {profile}.");}public Task<IActionResult>OnPostDisableAsync(Guid id,CancellationToken ct)=>Change(id,ct,m=>m.Disable(),"AccountUserBlocked","Vínculo bloqueado.");public Task<IActionResult>OnPostReactivateAsync(Guid id,CancellationToken ct)=>Change(id,ct,m=>m.Reactivate(),"AccountUserReactivated","Vínculo reativado.");public Task<IActionResult>OnPostDeleteAsync(Guid id,CancellationToken ct)=>Change(id,ct,m=>m.MarkAsDeleted(),"AccountUserSoftDeleted","Vínculo excluído logicamente.");private async Task<IActionResult>Change(Guid id,CancellationToken ct,Action<AccountMember>action,string auditAction,string summary){if(current.AccountId is not Guid account)return Forbid();var member=await db.AccountMembers.SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==account&&!x.IsDeleted,ct);if(member is null)return NotFound();action(member);db.AccountModuleAuditLogs.Add(new(){AccountId=account,ActorUserId=current.UserId,Action=auditAction,EntityType=nameof(AccountMember),EntityId=id.ToString(),Summary=summary,CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return auditAction.EndsWith("Deleted")?RedirectToPage("Index"):RedirectToPage(new{id});}}
